"""The compiled code cave (./build.sh), appended after the stock image, plus our version text on the screens."""
import os
import struct

from thumb import ROOT, symbols
from savexml import PATCHES as SAVEXML   # the streamed preset writer's five call sites (patches/savexml.py)

STOCK_END = 0x080F1E78
BUILD = b"Z"  # Tools screen shows 3.1.<BUILD>; S = solo, T = + slice knobs, U = + ducking (crashed: heap), V = U with state moved off the heap, W = duck shapes EXP1/EXP2/PUMP/LINR, X = + slicer Zoom knob, Y = + Keys screen chords, Z = chord label shortened to fit the button, a = six more chord shapes (Opn Shl Qrt + parallel m7 m9 Mj7), b = + sequence note conditions A:B, PLAY list reordered around ALWAYS, c = + pad crunch, 24 dB SVF with resonance drive, CPU meter on the version label, d = crunch rates moved down (16k..2k), CPU meter in the global cell name, new pad overdrive, Interp / crunch on Slicer and Clip pads, compressor models, e = sequencer edits play this pass, f = Comp Thresh, Tools order, Saturation label, lenient solo check, g = crunch reads the app's Interp, Interp under Saturation, sequencer grace, h = Interp label -> Fidelity, i = reverb Type selector + Room, j = Room v2 (8 lines, diffusion, modulation), k = Munchi Delay in FX1, l = Fidelity machine modes (SP1200, SP-12, S950, MPC60), m = solo fix, FX pages rebuild on Type, Munchi Clock/Width/Duck, Room Size/Mod/Early/Width, n = SP Raw + Saturation as SP input drive, o = solo: Mute screen is always Solo while a set exists, restore posts every pad, full redraw on FX Type change, p = Room +5 dB, q = Master FX slot (VHS) + Compressor / Master FX knob pages from INFO on Tools, r = INFO opens the page of the selected Tools row, s = Relapse, a memory echo as delay Type 3, t = MUTE / SOLO on the Pads screen (third position of the lower-right knob), u = Fidelity S1000: eight-point windowed-sinc re-pitch, v = Relapse's Reach knob off the reserved id 0x1e5, S1000 moved next to the machines, Pads MUTE always acts + button lights, w = ENV (the pad's ADSR) as a modulation source, x = the effects' final names on screen (Relapse, Reach, VHS), y = Smash in the compressor list (three-band up + down, Depth / Time on the Compressor page), global settings store 64 -> 96 entries, z = Confetti: granular micro-looper as delay Type 4 (Loops, Cloud, Slide, Stutter, Arp, Taps), A (after z) = Prism: four-block multi-effect as Master FX type 2 (Drive, Motion, Space, Texture; 20 effects), its memory from the SDRAM permanent allocator at boot, B = final names for Smash, Confetti and 13 knob / mode / effect labels, C = LFO 2 and LFO 3 per pad (sources LFO2 / LFO3, an LFO+ tab with Wave / Rate / Trig / Offset each), pad settings store 64 -> 96 entries, D = ENV, LFO2 and LFO3 on Clip and Slicer pads too (engine class B), with the LFO+ tab, E = code, file names and settings keys carry the same names as the screen (saved Relapse knob values from before E are not read), F = the LFO+ page, its defaults and Fidelity under Saturation also in the second copy of the pad pages (cells of class type 0x4c), G = pad stores really 96 entries (LFO 3 knobs), Prism on two plain pages (no Edit), master pages titled in the header, load left of the version on Tools, Space line no longer cleared in one block, H = G made to fit: the image must end by 0x08100000 (G was 76 bytes over and the installer refused it), Prism and the LFO code compiled for size, I = load in the empty middle label of the Tools bar, master page titles cut to 8 characters (longer ones wrapped), J = space clean-up: once-per-block effects and Munchi compiled for size, one reverb shared by Confetti and Prism, Static gentler low on its knob, K = J + USB device probe on the power jack (second controller, PB14 / PB15, polled from the audio wait), L = the power jack is a class-compliant USB MIDI device "Blackbox": in through stock's USB-host event parser, out from stock's to-USB queue, M = + USB audio to the computer: the three stereo outputs, 6 channels of 24-bit at 48 kHz, N = M + debug peek / poke over USB control requests and interrupt counters (not for release), O = USB audio carries Out 1 and the two other outputs (M sent the headphone mix as its first pair and missed one output), P = USB 3-4 is Out 2 and 5-6 is Out 3 (O had those two swapped; measured with a hat on Out 2), Q = USB MIDI in taken by the interrupt (several packets a block), incoming clock ticks stamped to where in the block they arrived, a repeated Start or Stop not sent to the computer twice, R = Q without the tick stamping (measured: no gain over the sequencer's own timing), S = R + record pre-roll: Tools > Rec > Pre-roll Off / 1 / 2 / 4 / 8 bars, the loop plays that long before a WAV recording starts, T = S950 modes rebuilt from the machine's schematic and OS, S950 Lo, Munchi's engine and S1000 out for room, U = Fidelity machine modes' pitch side on Clip / Slicer pads, second voice object gets its pad's Fidelity, V = piano roll Event editor: the top-right knob rotates the sequence, W (second time round) = KEY in the pad modulation Source list (stock's own per-note key source, never in the menu), X (second time round) = Fidelity SP 45: an SP-1200 that sampled the pad at 45 rpm and plays it back down, last in the list, Y (second time round) = one insert effect per pad: Insert row on the Conf tab, INFO opens its knob page; Phaser (Pebble, Ninety, Vibe, Deep, Steps) and Flanger (Electra, Jet, Tape, Metal), Z (second time round) = master clipper after the compressor (Clipper Off / Clean / Diode, Clip, Shape on the Compressor page), Tools rows in signal order: Master FX above Compressor

# The version text itself is `fw_version` in src/cpu.c, which lives in the cave. Stock's "3.1.9" at 0x080cf290 is
# NOT touched: its last character is pooled as the standalone "9" that the naming keyboard and two numeric lists
# use, so overwriting it made the 9 key type the build letter (a user hit this on the public 3.1.n). These four
# words are the literal-pool entries that point at the version for display; they are repointed at ours instead.
# Names so far: ... 3.2.a Motion on the delay's repeats; 3.2.b Motion listed once + SP 45 beside S950 Lo;
# 3.2.c the keyboard's 9 fixed (and the version text is now any length, not just five characters);
# 3.2.d Gate as a third per-pad insert type, with its own knobs (Thresh / Attack / Hold / Release / Floor / Mix);
# 3.2.e the live audio input playable through a pad: its insert, its sends, the master FX and the clipper.
# 3.2.w = 3.2.e's live input ported alone onto 3.2.v (did not boot); 3.2.x = its fix (the input bus through the
# engine pointer, the flag cleared at boot); 3.2.y the card loader's first stage: it reads BBEXTRA.BIN off the card
# and marks the version + / - / ?, and writes nothing.
VERSION_REFS = (0x0809AF30, 0x080AEAF4, 0x080C55E8, 0x080C72C8)
_sym = symbols(os.path.join(ROOT, "out", "cave.elf"))

PATCHES = [
    *[(a, struct.pack("<I", 0x080CF290), struct.pack("<I", _sym["fw_version"])) for a in VERSION_REFS],
    (STOCK_END, b"", open(os.path.join(ROOT, "out", "cave.bin"), "rb").read()),
] + SAVEXML
